<template><div class="app-container"><el-card><template #header>评审工作台</template><el-table :data="reviews"><el-table-column prop="reviewId" label="评审编号" width="100" /><el-table-column prop="title" label="评审标题" /><el-table-column prop="reviewer" label="评审人" width="120" /><el-table-column prop="status" label="状态" width="100"><template #default="scope"><el-tag :type="scope.row.status==='PASSED'?'success':scope.row.status==='REJECTED'?'danger':'warning'">{{scope.row.status}}</el-tag></template></el-table-column><el-table-column prop="reviewDate" label="评审日期" width="120" /><el-table-column label="操作" width="150"><template #default="scope"><el-button link type="primary" @click="handleView(scope.row)">查看详情</el-button><el-button link type="success" @click="handlePass(scope.row)" v-if="scope.row.status==='PENDING'">通过</el-button></template></el-table-column></el-table></el-card></div></template>
<script setup lang="ts">import { ElMessage } from 'element-plus';const reviews=[{reviewId:1,title:'服务器配置方案A评审',reviewer:'张工',status:'PENDING',reviewDate:'2026-06-09'},{reviewId:2,title:'存储方案B技术评审',reviewer:'李工',status:'PASSED',reviewDate:'2026-06-08'},{reviewId:3,title:'网络方案C合规评审',reviewer:'王工',status:'REJECTED',reviewDate:'2026-06-07'}];const handleView=(row:any)=>{ElMessage.info('查看评审: '+row.title)};const handlePass=(row:any)=>{ElMessage.success('评审已通过: '+row.title)}</script>
